<!-- This file is generated by AI. -->
<!--
  右键 / 下拉菜单 (全项目唯一的一个)。

  定位要点: 先用请求坐标渲染, 再在**同一帧内**量出实际尺寸并夹进视口 —— 贴着屏幕边缘打开的菜单
  不夹就会有一部分落在视口外。最终坐标存局部 state, 只在量完之后赋值。

  不用 portal: 与项目其余弹层一致, `position: fixed` 已经足够。
-->
<script lang="ts">
  import { tick } from 'svelte';

  import Icon from './Icon.svelte';
  import type { IconName } from './icons';

  export interface ContextMenuItem {
    key: string;
    /** 菜单项文字 (分隔项不需要) */
    label?: string;
    iconName?: IconName;
    /** 危险操作 (删除/放弃) 红色显示 */
    danger?: boolean;
    disabled?: boolean;
    /** 悬浮提示 */
    title?: string;
    /** 这是分隔线而不是菜单项 */
    separator?: boolean;
    onClick?: () => void;
  }

  let {
    /** 请求的屏幕坐标 (来自鼠标事件或触发按钮的 rect) */
    x,
    y,
    items,
    onClose,
  }: {
    x: number;
    y: number;
    items: ContextMenuItem[];
    onClose: () => void;
  } = $props();

  const MARGIN = 8;

  let node: HTMLDivElement | undefined = $state();

  /*
   * 最终坐标。`null` = "还没量出来", 此时**直接按请求坐标渲染**。
   *
   * 刻意**不**写 `$state(x)`: 那等于把 props 的**初值**烧进 state, 组件实例被复用 (同一个
   * 菜单换坐标重新打开) 时第一帧会画在**上一次**的坐标上, 直到 effect 量完才纠正; 编译器也会
   * 报 `state_referenced_locally`。
   */
  let left = $state<number | null>(null);
  let top = $state<number | null>(null);

  /**
   * 量出真实尺寸后夹进视口。
   *
   * 同步读取 `x`/`y`/`items.length` 建立响应式依赖 (换了目标就重新夹一次), 再把最终坐标写成
   * state —— 只触发一次重排, 不会循环 (坐标变化不改变尺寸)。开头的 `left = null` 让**换坐标
   * 后的第一帧**回到请求坐标, 而不是停在上一次的夹取结果。
   */
  $effect(() => {
    const requestedX = x;
    const requestedY = y;
    const count = items.length;
    void count;
    left = null;
    top = null;
    void tick().then(() => {
      if (!node) return;
      const rect = node.getBoundingClientRect();
      const maxLeft = window.innerWidth - rect.width - MARGIN;
      const maxTop = window.innerHeight - rect.height - MARGIN;
      left = Math.max(MARGIN, Math.min(requestedX, maxLeft));
      top = Math.max(MARGIN, Math.min(requestedY, maxTop));
    });
  });

  function handleKeydown(event: KeyboardEvent) {
    if (event.key !== 'Escape') return;
    event.stopPropagation();
    onClose();
  }

  function handleResize() {
    onClose();
  }

  function runItem(item: ContextMenuItem): void {
    if (item.disabled || item.separator) return;
    /*
     * 顺序必须是"先执行、后关闭"。
     *
     * 先 `onClose()` 会把调用方的 `menu` 状态置空, 而调用方常用 `$derived` 从它推出"当前
     * 操作的对象" (例如 `WelcomePage` 的 `menuProject`) —— 回调里再读就是 `undefined`, 抛出的
     * 异常又不会显示给用户, 看起来就是"菜单里每一项点了都没反应"。
     *
     * 调换顺序不会让菜单残留: `onClose()` 是同步的, Svelte 在这次事件处理结束后才刷新,
     * 回调里打开的对话框不会被菜单盖住。
     */
    item.onClick?.();
    onClose();
  }
</script>

<svelte:window onkeydown={handleKeydown} onresize={handleResize} />

<!--
  透明遮罩: 点空白处关闭。放在菜单之前, 因此不会挡住菜单自身的点击。

  **类名必须是 `.context-menu-backdrop`**: 它带 `z-index: 2500`, 高于 `.modal-backdrop`(2000)
  与 `.scene-picker-menu`(1000)。菜单在对话框里也要能用, 点遮罩还要能盖住下面那些浮层 ——
  换成一个低 z-index 的新类名, 菜单就会漂浮在对话框之上且点对话框不关菜单。
-->
<div
  class="context-menu-backdrop"
  role="presentation"
  onclick={onClose}
  oncontextmenu={(event) => {
    event.preventDefault();
    onClose();
  }}
></div>

<div bind:this={node} class="context-menu" style="left:{left ?? x}px; top:{top ?? y}px" role="menu">
  {#each items as item (item.key)}
    {#if item.separator}
      <div class="context-menu-separator" role="separator"></div>
    {:else}
      <button
        type="button"
        role="menuitem"
        class="context-menu-item"
        class:danger={item.danger}
        disabled={item.disabled}
        title={item.title}
        onclick={() => runItem(item)}
      >
        {#if item.iconName}<Icon name={item.iconName} size={16} />{/if}
        <span class="context-menu-label">{item.label}</span>
      </button>
    {/if}
  {/each}
</div>
